-- Reviewed-by: Claude (agent, #22)
-- Feature flags and the access-mode registry (#22, spike §4.2, docs/engineering/flags.md).
--   * feature_flag (global, staff-managed rows keyed by flag key) and access_mode_registry (court
--     adapter access modes, off by default) are global tables (GLOBAL_TABLES).
--   * workspace_feature_flag holds per-workspace overrides: a tenant table under FORCE RLS with the
--     standard ws_isolation policy (tenantPolicy()), registered in the cross-tenant suite.
--   * access_mode is a closed enum (ADR 0011): no member permits unauthorised court scraping or
--     captcha circumvention.
--   * app_notify_flag_changed() fires pg_notify('flag_changed', key) after any write to either flag
--     table, so server processes drop their cached evaluations (packages/flags/src/cache.ts).
-- New tables, a type and a function only: nothing existing is altered or dropped.
CREATE TYPE "public"."access_mode" AS ENUM('user_supplied', 'device_user_triggered', 'official', 'licensed', 'none');--> statement-breakpoint
CREATE TABLE "access_mode_registry" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"adapter_id" text NOT NULL,
	"resource" text NOT NULL,
	"mode" "access_mode" NOT NULL,
	"counsel_note" text,
	"reviewed_by" uuid,
	"reviewed_at" timestamp with time zone,
	"enabled" boolean DEFAULT false NOT NULL,
	CONSTRAINT "access_mode_registry_adapter_resource_uq" UNIQUE("adapter_id","resource")
);
--> statement-breakpoint
