	"workspace_id" uuid NOT NULL,
	CONSTRAINT "workspace_feature_flag_workspace_key_uq" UNIQUE("workspace_id","key"),
	CONSTRAINT "workspace_feature_flag_legal_ack_chk" CHECK (legal_ack_by is null or legal_ack_note is not null)
);
