CREATE FUNCTION app_notify_flag_changed() RETURNS trigger
  LANGUAGE plpgsql SECURITY INVOKER SET search_path = public, pg_temp
  AS $$
  BEGIN
    PERFORM pg_notify('flag_changed', coalesce(NEW.key, OLD.key));
    RETURN NULL;
  END
  $$;--> statement-breakpoint
CREATE TRIGGER feature_flag_notify AFTER INSERT OR UPDATE OR DELETE ON "feature_flag"
  FOR EACH ROW EXECUTE FUNCTION app_notify_flag_changed();--> statement-breakpoint
CREATE TRIGGER workspace_feature_flag_notify AFTER INSERT OR UPDATE OR DELETE ON "workspace_feature_flag"
  FOR EACH ROW EXECUTE FUNCTION app_notify_flag_changed();--> statement-breakpoint
REVOKE ALL ON FUNCTION app_notify_flag_changed() FROM PUBLIC;--> statement-breakpoint
